import {prepareAvatar} from './avatar.js';
import {effortSummary} from './effort.js';
import {DAY,intervals,reviewPlan} from './review-schedule.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],KEY='yohaku-data-v1',POPUP_DURATION=1000;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DEFAULT_CATEGORIES=['語学','仕事','読書','その他'];
function categoryKey(name){return name.normalize('NFKC').toLocaleLowerCase('ja-JP')}
function emptyState(){return {items:[],logs:[],categories:[...DEFAULT_CATEGORIES]}}
function normalizeState(x){if(!x||!Array.isArray(x.items)||!Array.isArray(x.logs))return emptyState();delete x.popup;const names=Array.isArray(x.categories)?x.categories.filter(c=>typeof c==='string'&&c.trim()):DEFAULT_CATEGORIES;x.categories=[...new Set([...names,...x.items.map(i=>i.category).filter(c=>typeof c==='string'&&c.trim())])];if(!x.categories.length)x.categories=[...DEFAULT_CATEGORIES];return x}
function readLegacy(){try{return normalizeState(JSON.parse(localStorage.getItem(KEY)))}catch{return emptyState()}}
let state=emptyState(),view='home',editId=null,currentId=null,revealed=false,queue=[],dismissed=new Map(),categoryEditName=null,returnToEditor=false,reviewDismissTimer=null;
let currentUser=null,cloudRevision=0,cloudReady=false,syncTimer=null,syncInFlight=null,dirty=false,pendingVersion=0,adminEditId=null,accounts=[],pendingDeleteId=null,adminAvatarData='',profileAvatarData=null,adminCreateMode=false;
const cacheKey=()=>KEY+':account:'+currentUser.id;
function setSyncStatus(text,retry=false){$('#syncStatus').textContent=text;$('#retrySync').hidden=!retry}
function save(){if(!currentUser||!cloudReady)return false;try{dirty=true;pendingVersion++;cacheState();setSyncStatus('端末に保存済み・同期中…');clearTimeout(syncTimer);syncTimer=setTimeout(syncNow,250);return true}catch{toast('この端末に保存できませんでした。空き容量をご確認ください。');return false}}
function cacheState(){localStorage.setItem(cacheKey(),JSON.stringify({data:state,revision:cloudRevision,dirty}))}
async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await response.json().catch(()=>({error:'サーバーに接続できませんでした。'}));if(!response.ok)throw Object.assign(new Error(data.error||'処理できませんでした。'),{status:response.status});return data}
function showRecovery(){cloudReady=false;$('#appShell').hidden=true;$('#authScreen').hidden=true;$('#syncRecovery').hidden=false;$('#recoveryMessage').textContent=currentUser.email+' のデータが別の画面で更新されています。'}
async function syncNow(){clearTimeout(syncTimer);if(syncInFlight)return syncInFlight;if(!currentUser||!cloudReady||!dirty)return;const version=pendingVersion,payload=structuredClone(state),userId=currentUser.id;syncInFlight=(async()=>{try{const result=await api('/api/data',{method:'PUT',body:JSON.stringify({data:payload,revision:cloudRevision})});if(currentUser?.id!==userId)return;cloudRevision=result.revision;dirty=pendingVersion!==version;cacheState();setSyncStatus(dirty?'変更を同期中…':'クラウドに保存済み');}catch(e){if(e.status===409){showRecovery()}else setSyncStatus(e.status===401?'ログインの有効期限が切れました。ログインし直してください。':'端末に保存済み・同期できませんでした。',true)}finally{syncInFlight=null}})();await syncInFlight;if(dirty&&cloudReady&&pendingVersion!==version)syncTimer=setTimeout(syncNow,250)}
async function loadLearning(){cloudReady=false;const result=await api('/api/data');cloudRevision=result.revision;let cached;try{cached=JSON.parse(localStorage.getItem(cacheKey()))}catch{}if(cached?.dirty&&cached.revision!==cloudRevision){state=normalizeState(cached.data);dirty=true;showRecovery();return}state=normalizeState(cached?.dirty?cached.data:result.data);dirty=!!cached?.dirty;cloudReady=true;cacheState();$('#authScreen').hidden=true;$('#syncRecovery').hidden=true;$('#appShell').hidden=false;renderProfile();$('#masterNav').hidden=!currentUser.isMaster;$('#appShell').classList.toggle('master-session',currentUser.isMaster);$('#importLegacy').hidden=!readLegacy().items.length;setView('home');setSyncStatus(dirty?'端末の変更を同期中…':'クラウドに保存済み');if(dirty)syncNow();setTimeout(checkDue,1800)}
function lockApp(message=''){currentUser=null;profileAvatarData=null;$$('[data-current-avatar]').forEach(el=>{el.textContent='K';el.classList.remove('has-image')});$('#profileEmail').textContent='My learning space';$('#profileEmail').title='';cloudReady=false;state=emptyState();dirty=false;clearTimeout(reviewDismissTimer);clearTimeout(syncTimer);queue=[];dismissed.clear();currentId=null;$('#editor').close();$('#review').close();$('#deleteAccountDialog').close();pendingDeleteId=null;$('#masterNav').hidden=true;$('#appShell').classList.remove('master-session');$('#appShell').hidden=true;$('#syncRecovery').hidden=true;$('#authScreen').hidden=false;$('#loginPassword').value='';$('#loginError').textContent=message;$('#loginError').hidden=!message;$('#sessionLoading').hidden=true;$('#search').value='';$('#filter').value='';$('#editForm').reset();$('#reviewContent').innerHTML='';accounts=[];$('#accountList').innerHTML='';resetCategoryForm();resetAdminForm();render()}
async function initSession(){try{const result=await api('/api/session');currentUser=result.user;await loadLearning()}catch(e){lockApp(e.status===401?'':e.message)}finally{$('#sessionLoading').hidden=true}}
async function login(e){e.preventDefault();$('#loginSubmit').disabled=true;$('#loginError').hidden=true;try{const result=await api('/api/session',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value.trim(),password:$('#loginPassword').value})});currentUser=result.user;$('#loginPassword').value='';await loadLearning()}catch(e){lockApp(e.message)}finally{$('#loginSubmit').disabled=false}}
async function logout(){await syncNow();if(dirty&&!confirm('未同期の変更は、この端末に保持されます。ログアウトしますか？'))return;try{await api('/api/session',{method:'DELETE'});lockApp()}catch(e){toast(e.message)}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),POPUP_DURATION)}
function date(t,full=false){return new Intl.DateTimeFormat('ja-JP',{month:'long',day:'numeric',...(full?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(t))}
function dayKey(t){return new Date(t).toLocaleDateString('sv-SE')}
const due=()=>state.items.filter(x=>x.next<=Date.now()).sort((a,b)=>a.next-b.next);
function icon(c){return c==='語学'?['Aa','']:c==='仕事'?['⌘','work']:c==='読書'?['▤','book']:['✧','']}
function card(x,all=false){const [symbol,cls]=icon(x.category);return `<article class="review-card"><div class="category-icon ${cls}">${symbol}</div><div class="details"><span class="tag">${escapeHTML(x.category)} · ${x.count||0}回復習</span><h3>${escapeHTML(x.title)}</h3><small>${x.next<=Date.now()?'● 復習のタイミングです':`次回 ${date(x.next,true)}`}</small></div>${all?`<div class="library-actions"><button class="review-btn" data-review="${x.id}">復習</button><button class="text-button" data-edit="${x.id}">編集</button><button class="text-button" data-delete="${x.id}">削除</button></div>`:`<button class="review-btn" data-review="${x.id}">復習する ↗</button>`}</article>`}
function render(){const ds=due(),logs=state.logs.filter(x=>dayKey(x.at)===dayKey(Date.now()));$('#today').textContent=new Intl.DateTimeFormat('ja-JP',{year:'numeric',month:'long',day:'numeric',weekday:'short'}).format(new Date());$('#navcount').textContent=state.items.length;$('#dueStat').innerHTML=ds.length+'<small>件</small>';$('#allStat').innerHTML=state.items.length+'<small>件</small>';$('#doneStat').innerHTML=logs.length+'<small>回</small>';$('#totalStat').innerHTML=state.logs.length+'<small>回</small>';$('#heroCount').textContent=ds.length+'件';$('#dueBadge').textContent=ds.length;$('#dueList').innerHTML=ds.length?ds.slice(0,4).map(x=>card(x)).join(''):`<div class="empty"><strong>${state.items.length?'今日の復習は、ひとやすみ。':'最初の学びを、植えてみましょう。'}</strong>${state.items.length?'次のタイミングになったら、お知らせします。':'覚えておきたいことを登録して、記憶を育てよう。'}<br><button class="text-button" id="emptyAdd">＋ 学びを登録する</button></div>`;
renderEffort();refreshCategoryOptions();renderLibrary();renderSchedule();renderCategoryList();if(view==='settings')renderSettings();}
function renderLibrary(){const q=$('#search').value.toLowerCase(),c=$('#filter').value,items=state.items.filter(x=>(!c||x.category===c)&&(x.title+' '+x.body).toLowerCase().includes(q));$('#libraryList').innerHTML=items.length?items.map(x=>card(x,true)).join(''):'<div class="empty">学びが見つかりません。新しい学びを登録してみましょう。</div>'}
function renderSchedule(){const items=[...state.items].sort((a,b)=>a.next-b.next);let prev='';$('#schedule').innerHTML=items.length?items.map(x=>{const k=dayKey(x.next),head=k!==prev?`<h2 class="schedule-day">${x.next<=Date.now()?'復習待ち · ':''}${date(x.next)} <span class="muted">${new Date(x.next).getFullYear()}</span></h2>`:'';prev=k;return head+card(x,true)}).join(''):'<div class="empty">学びを登録すると、ここに復習予定が並びます。</div>'}

function refreshCategoryOptions(){
 const options=state.categories.map(name=>`<option value="${escapeHTML(name)}">${escapeHTML(name)}</option>`).join('');
 const input=$('#categoryInput'),filter=$('#filter'),selected=input.value,filtered=filter.value;
 if(input.dataset.options!==options){input.innerHTML=options;input.dataset.options=options;input.value=state.categories.includes(selected)?selected:state.categories[0]}
 if(filter.dataset.options!==options){filter.innerHTML='<option value="">すべてのカテゴリー</option>'+options;filter.dataset.options=options;filter.value=state.categories.includes(filtered)?filtered:''}
}
function renderCategoryList(){
 $('#categoryList').innerHTML=state.categories.map(name=>{const count=state.items.filter(x=>x.category===name).length,blocked=count>0||state.categories.length===1;return `<article class="category-row"><span class="category-icon" aria-hidden="true">◇</span><div class="category-info"><h3>${escapeHTML(name)}</h3><small>${count}件の学び${count?' · 使用中':''}</small></div><div class="category-actions"><button class="secondary" data-category-edit="${escapeHTML(name)}" aria-label="${escapeHTML(name)}の名前を変更">名前を変更</button><button class="text-button" data-category-delete="${escapeHTML(name)}" aria-label="${escapeHTML(name)}を削除" ${blocked?'disabled':''} title="${count?'使用中のカテゴリーは削除できません':state.categories.length===1?'カテゴリーは1つ以上必要です':'カテゴリーを削除'}">削除</button></div></article>`}).join('');
}
function resetCategoryForm(){categoryEditName=null;$('#categoryForm').reset();$('#categoryFormLabel').textContent='新しいカテゴリー';$('#categorySave').textContent='追加する';$('#categoryCancel').hidden=true;$('#categoryError').hidden=true}
function editCategory(name){categoryEditName=name;$('#categoryName').value=name;$('#categoryFormLabel').textContent='カテゴリーの名前を変更';$('#categorySave').textContent='変更を保存';$('#categoryCancel').hidden=false;$('#categoryError').hidden=true;$('#categoryName').focus()}
function categoryError(message){$('#categoryError').textContent=message;$('#categoryError').hidden=false;$('#categoryName').focus()}
function commitCategoryChange(change){const before=structuredClone(state);change();if(!save()){state=before;return false}refreshCategoryOptions();render();return true}
function submitCategory(e){e.preventDefault();const name=$('#categoryName').value.trim();if(!name||name.length>40){categoryError('カテゴリー名を1〜40文字で入力してください。');return}if(state.categories.some(c=>c!==categoryEditName&&categoryKey(c)===categoryKey(name))){categoryError('同じ名前のカテゴリーがあります。');return}if(categoryEditName&&!state.categories.includes(categoryEditName)){categoryError('このカテゴリーは別の画面で変更されました。キャンセルしてやり直してください。');return}const old=categoryEditName,selected=$('#categoryInput').value,filtered=$('#filter').value;if(!commitCategoryChange(()=>{if(old){state.categories=state.categories.map(c=>c===old?name:c);state.items.forEach(x=>{if(x.category===old)x.category=name})}else state.categories.push(name)}))return;if(old&&selected===old)$('#categoryInput').value=name;if(old&&filtered===old){$('#filter').value=name;renderLibrary()}if(!old&&returnToEditor)$('#categoryInput').value=name;resetCategoryForm();toast(old?'カテゴリー名を変更しました':'カテゴリーを追加しました')}
function deleteCategory(name){if(state.items.some(x=>x.category===name)||state.categories.length===1){toast('使用中、または最後のカテゴリーは削除できません。');return}if(!confirm('カテゴリー「'+name+'」を削除しますか？'))return;if(commitCategoryChange(()=>{state.categories=state.categories.filter(c=>c!==name)})){if(categoryEditName===name)resetCategoryForm();toast('カテゴリーを削除しました')}}

function renderSettings(){profileAvatarData=null;$('#settings').innerHTML=`<section class="settings-panel profile-panel"><div class="eyebrow">YOUR PROFILE</div><h2>あなたのプロフィール</h2>${currentUser?.isMaster?`<div class="profile-current-avatar">${avatarMarkup(currentUser.avatarData,'あなたのアイコン')}</div>`:''}<p class="profile-address">${escapeHTML(currentUser?.email||'')}</p>${currentUser?.isMaster?`<p>名前：<strong>${escapeHTML(currentUser.displayName||'名前未設定')}</strong></p><p class="muted">マスターの名前・アイコンはアカウント管理から変更できます。</p><button class="secondary" data-view="admin">アカウント管理で変更 ↗</button>`:`<form id="profileForm">${avatarEditor('profile',currentUser?.avatarData)}<label for="profileName">名前</label><input id="profileName" name="displayName" maxlength="80" autocomplete="nickname" value="${escapeHTML(currentUser?.displayName||'')}" placeholder="アプリで表示する名前" aria-describedby="profileNameHelp"><p id="profileNameHelp" class="muted">名前は80文字以内で設定できます。空欄で保存すると名前未設定になります。</p><p id="profileError" class="category-error" role="alert" hidden></p><button id="profileSave" class="primary" type="submit">プロフィールを保存</button></form>`}</section><section class="settings-panel">${currentUser?.isMaster?'<div class="master-entry"><span>♞ マスター管理</span><button class="primary" data-view="admin">利用者アカウントを管理 ↗</button></div>':''}<div class="eyebrow">YOUR RHYTHM</div><h2>あなたのペースで、続けよう。</h2><p>復習の目安は、前回の復習から次の間隔です。<br>「合格」なら1段階長く、「不合格」なら1段階短くなります。</p><div class="intervals">${intervals.map(x=>`<span>${x}日後</span>`).join('')}</div><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h2>復習のお知らせ</h2><p>復習のタイミングになると、アプリ内にポップアップが1秒間表示されます。復習は「今日の復習」からいつでも開けます。</p><button class="secondary" id="notifyEnable">ブラウザ通知を${'Notification'in window&&Notification.permission==='granted'?'テストする':'有効にする'}</button><p class="muted">通知はブラウザの対応・許可が必要です。復習内容とカテゴリーは、ログイン中のアカウントごとにクラウドへ保存されます。</p></section>`}
function setView(v){if(v==='admin'&&!currentUser?.isMaster)return;view=v;['home','library','schedule','settings','categories','admin'].forEach(x=>$('#'+x).hidden=x!==v);$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('#backToEditor').hidden=!(v==='categories'&&returnToEditor);const names={admin:['アカウント管理','','利用者の名前・メールアドレス・パスワードを管理します。'],categories:['カテゴリー設定','',''],home:['ダッシュボード','おかえりなさい。',''],library:['学びのライブラリ','',''],schedule:['復習スケジュール','',''],settings:['設定・通知','','']};$('#crumb').textContent=names[v][0];$('#heading').textContent=names[v][1];$('#heading').hidden=!names[v][1];$('#subtitle').textContent=names[v][2];$('#subtitle').hidden=!names[v][2];render();if(v==='admin')loadAccounts();window.scrollTo(0,0)}
function openEditor(id=null){editId=id;const item=state.items.find(x=>x.id===id);$('#editForm').reset();refreshCategoryOptions();$('#editTitle').textContent=item?'学びを編集':'新しい学びを登録';if(item){$('#titleInput').value=item.title;$('#bodyInput').value=item.body;$('#categoryInput').value=item.category}$('#editor').showModal()}
$('#editForm').addEventListener('submit',e=>{e.preventDefault();const title=$('#titleInput').value.trim(),body=$('#bodyInput').value.trim();if(!title||!body){toast('タイトルと復習内容を入力してください。');return}if(!state.categories.includes($('#categoryInput').value)){toast('カテゴリーを選択してください。');refreshCategoryOptions();return}if(editId){const x=state.items.find(x=>x.id===editId);Object.assign(x,{title,body,category:$('#categoryInput').value})}else state.items.push({id:crypto.randomUUID(),title,body,category:$('#categoryInput').value,created:Date.now(),next:Date.now()+DAY,step:0,scheduleVersion:2,count:0});if(save()){$('#editor').close();render();toast(editId?'学びを更新しました':'学びを登録しました。記憶を育てていきましょう。')}});
function startReview(id,automatic=false){clearTimeout(reviewDismissTimer);reviewDismissTimer=null;const x=state.items.find(x=>x.id===id);if(!x)return;currentId=id;revealed=false;drawReview();if(!$('#review').open)$('#review').showModal();if(automatic)reviewDismissTimer=setTimeout(dismissReview,POPUP_DURATION)}
function drawReview(){const x=state.items.find(x=>x.id===currentId);if(!x)return;const pass=reviewPlan(x,'good',state.logs),fail=reviewPlan(x,'again',state.logs);$('#reviewContent').innerHTML=`<p class="tag">${escapeHTML(x.category)} · ${x.count}回復習</p><h2>${escapeHTML(x.title)}</h2><p class="muted">まずは、答えを見ずに思い出してみましょう。</p>${revealed?`<div class="answer">${escapeHTML(x.body)}</div><p class="muted">内容を思い出せましたか？ 合格なら間隔を延ばし、不合格なら1段階戻します。</p><div class="review-grades"><button class="secondary" data-grade="again">不合格<small>${fail.days}日後</small></button><button class="primary" data-grade="good">合格<small>${pass.days}日後</small></button></div>`:`<div class="review-question">少し立ち止まって、<br>頭の中の記憶をたどってみよう。</div><button class="primary" id="reveal" style="width:100%">内容を表示する</button>`}`}
function grade(g){clearTimeout(reviewDismissTimer);reviewDismissTimer=null;const x=state.items.find(x=>x.id===currentId);if(!x)return;const plan=reviewPlan(x,g,state.logs);x.step=plan.step;x.scheduleVersion=plan.scheduleVersion;x.next=Date.now()+plan.days*DAY;x.count++;state.logs.push({id:x.id,at:Date.now(),grade:g});save();dismissed.delete(x.id);render();queue=queue.filter(id=>id!==x.id);const next=queue.shift();if(next)startReview(next);else{$('#review').close();currentId=null;toast('復習を記録しました。次回：'+date(x.next,true))}}
function dismissReview(){clearTimeout(reviewDismissTimer);reviewDismissTimer=null;if(currentId)dismissed.set(currentId,Date.now()+600000);queue=[];currentId=null;$('#review').close()}
function checkDue(){if(!currentUser||!cloudReady)return;render();if($('#editor').open||$('#review').open||(view==='categories'&&($('#categoryName').value.trim()||returnToEditor))||view==='admin'||document.visibilityState!=='visible')return;const items=due().filter(x=>(dismissed.get(x.id)||0)<=Date.now());if(items.length){queue=items.map(x=>x.id);startReview(queue.shift(),true);if('Notification'in window&&Notification.permission==='granted')try{new Notification('覚えKnight | 復習のタイミングです',{body:items.length+'件の学びを思い出しましょう。',tag:'yohaku-review'})}catch{}}}
async function notifications(){if(!('Notification'in window)){toast('このブラウザは通知に対応していません。');return}try{const p=await Notification.requestPermission();if(p==='granted'){new Notification('覚えKnight | 通知を設定しました',{body:'アプリを開いている間、復習タイミングをお知らせします。'});toast('ブラウザ通知を有効にしました')}else toast('ブラウザ設定で通知を許可してください。')}catch{toast('通知を設定できませんでした。')}renderSettings()}
document.addEventListener('click',e=>{if(e.target.closest('.brand')){e.preventDefault();setView('home');return}const b=e.target.closest('button');if(!b)return;if(b.dataset.view){if(b.dataset.view==='categories')returnToEditor=false;setView(b.dataset.view)}if(b.id==='manageCategories'){$('#editor').close();returnToEditor=true;setView('categories')}if(b.id==='backToEditor'){returnToEditor=false;setView('home');refreshCategoryOptions();$('#editor').showModal()}if(b.id==='categoryCancel')resetCategoryForm();if(b.hasAttribute('data-category-edit'))editCategory(b.dataset.categoryEdit);if(b.hasAttribute('data-category-delete'))deleteCategory(b.dataset.categoryDelete);if(b.id==='add'||b.id==='emptyAdd')openEditor();if(b.hasAttribute('data-close'))$('#editor').close();if(b.dataset.review){queue=[];startReview(b.dataset.review)}if(b.dataset.edit)openEditor(b.dataset.edit);if(b.dataset.delete){const x=state.items.find(x=>x.id===b.dataset.delete);if(confirm('「'+x.title+'」を削除しますか？')){state.items=state.items.filter(x=>x.id!==b.dataset.delete);save();render();toast('学びを削除しました')}}if(b.id==='reveal'){revealed=true;drawReview()}if(b.dataset.grade)grade(b.dataset.grade);if(b.hasAttribute('data-review-close'))dismissReview();if(b.id==='start'){queue=due().map(x=>x.id);if(queue.length)startReview(queue.shift());else toast('今は復習待ちの学びがありません。')}if(b.id==='viewAll')setView('library');if(b.id==='bell')setView('settings');if(b.id==='notifyEnable')notifications()});
$('#categoryForm').addEventListener('submit',submitCategory);
$('#categoryName').addEventListener('input',()=>{$('#categoryError').hidden=true});
$('#search').addEventListener('input',renderLibrary);$('#filter').addEventListener('change',renderLibrary);$('#review').addEventListener('cancel',e=>{e.preventDefault();dismissReview()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkDue()});window.addEventListener('storage',e=>{if(currentUser&&e.key===cacheKey()&&!dirty&&!syncInFlight){loadLearning().catch(()=>setSyncStatus('同期できませんでした。',true))}});window.addEventListener('online',syncNow);window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});initSession();setInterval(checkDue,30000);

function resetAdminForm(create=false){adminCreateMode=create;adminEditId=null;adminAvatarData='';$('#adminAvatarEditor').innerHTML=avatarEditor('admin','');$('#adminForm').reset();$('#adminEmailField').hidden=false;$('#adminEmail').disabled=false;$('#adminPasswordField').hidden=false;$('#adminPassword').disabled=false;$('#adminFormTitle').textContent='新しい利用者を追加';$('#adminPasswordLabel').textContent='初期パスワード';$('#adminPassword').required=true;$('#adminSubmit').textContent='利用者を追加';$('#adminCancel').hidden=true;$('#adminError').hidden=true;$('#adminTarget').value='__new__';$('#adminModeNote').textContent='新規利用者の画像です。「利用者を追加」でアカウントと一緒に保存されます。'}
function renderAccounts(){if(!currentUser?.isMaster){$('#accountList').innerHTML='';return} $('#accountList').innerHTML=accounts.map(a=>`<article class="category-row">${avatarMarkup(a.avatar_data,a.display_name||'アカウントのアイコン')}<div class="category-info"><h3>${escapeHTML(a.display_name||'名前未設定')}</h3><p class="account-email">${escapeHTML(a.email)}</p><p class="account-credential"><span>保存済みパスワード</span> ${a.password?`<code>${escapeHTML(a.password)}</code>`:'<small>未保存（次回ログインまたは再設定後に表示）</small>'}</p><small>${a.user_id===currentUser.id?'マスター':a.active?'利用中':'利用停止中'}</small></div>${a.managed_by_knight?`<div class="category-actions"><button class="secondary" data-account-edit="${a.user_id}">編集・再設定</button><button class="text-button" data-account-toggle="${a.user_id}">${a.active?'利用停止':'利用再開'}</button><button class="text-button account-delete" data-account-delete="${a.user_id}" aria-label="${escapeHTML(a.email)}を削除">削除</button></div>`:`<button class="secondary" data-account-edit="${a.user_id}">プロフィールを編集</button>`}</article>`).join('')}
async function loadAccounts(){if(!currentUser?.isMaster)return;$('#adminListError').hidden=true;const owner=currentUser.id;try{const result=await api('/api/admin');if(currentUser?.id!==owner)return;accounts=result.accounts;renderAdminTarget();const me=accounts.find(a=>a.user_id===currentUser.id);if(me){currentUser.displayName=me.display_name||'';currentUser.avatarData=me.avatar_data||'';renderProfile()}renderAccounts();if(!adminCreateMode&&!adminEditId){let preferred;try{preferred=sessionStorage.getItem('knight-admin-target:'+owner)}catch{}editAccount(accounts.some(a=>a.user_id===preferred)?preferred:owner)}}catch(e){$('#adminListError').textContent=e.message;$('#adminListError').hidden=false}}
function editAccount(id){if(!currentUser?.isMaster)return;const a=accounts.find(x=>x.user_id===id);if(!a)return;adminCreateMode=false;adminEditId=id;$('#adminTarget').value=id;$('#adminModeNote').textContent=(a.display_name||a.email)+' のアイコンは、画像を選ぶとこのユーザーへ自動保存されます。';try{sessionStorage.setItem('knight-admin-target:'+currentUser.id,id)}catch{}adminAvatarData=a.avatar_data||'';$('#adminAvatarEditor').innerHTML=avatarEditor('admin',adminAvatarData);$('#adminName').value=a.display_name||'';const master=a.user_id===currentUser.id;$('#adminEmailField').hidden=master;$('#adminEmail').disabled=master;$('#adminPasswordField').hidden=master;$('#adminPassword').disabled=master;$('#adminEmail').value=a.email;$('#adminPassword').value='';$('#adminPassword').required=false;$('#adminPasswordLabel').textContent='新しいパスワード（変更する場合のみ）';$('#adminFormTitle').textContent=(a.display_name||a.email)+' のプロフィール';$('#adminSubmit').textContent='変更を保存';$('#adminCancel').hidden=false;$('#adminError').hidden=true;$('#adminName').focus()}
async function submitAccount(e){e.preventDefault();if(!currentUser?.isMaster)return;$('#adminSubmit').disabled=true;$('#adminError').hidden=true;const displayName=$('#adminName').value.trim(),email=$('#adminEmail').value.trim().toLowerCase(),password=$('#adminPassword').value;try{const savedId=adminEditId,body=adminEditId?{action:'update',userId:adminEditId,displayName,avatarData:adminAvatarData,...(adminEditId===currentUser.id?{}:{...(email!==accounts.find(a=>a.user_id===adminEditId)?.email?{email}:{}),...(password?{password}:{})})}:{action:'create',displayName,avatarData:adminAvatarData,email,password};await api('/api/admin',{method:'POST',body:JSON.stringify(body)});await loadAccounts();const savedAccount=accounts.find(a=>savedId?a.user_id===savedId:a.email===email);if(savedAccount)editAccount(savedAccount.user_id);toast('アカウントを保存しました')}catch(e){$('#adminError').textContent=e.message;$('#adminError').hidden=false}finally{$('#adminSubmit').disabled=false}}
async function toggleAccount(id){if(!currentUser?.isMaster)return;const a=accounts.find(x=>x.user_id===id);if(!a||!confirm(a.email+' の利用を'+(a.active?'停止':'再開')+'しますか？'))return;try{await api('/api/admin',{method:'POST',body:JSON.stringify({action:'update',userId:id,active:!a.active})});await loadAccounts();toast('利用状態を更新しました')}catch(e){$('#adminListError').textContent=e.message;$('#adminListError').hidden=false}}
$('#loginForm').addEventListener('submit',login);$('#logout').addEventListener('click',logout);$('#recoveryLogout').addEventListener('click',logout);$('#retrySync').addEventListener('click',()=>{if($('#syncStatus').textContent.includes('有効期限'))logout();else syncNow()});$('#adminForm').addEventListener('submit',submitAccount);$('#adminCancel').addEventListener('click',()=>{adminCreateMode=false;editAccount(currentUser.id)});$('#refreshAccounts').addEventListener('click',loadAccounts);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.accountEdit)editAccount(b.dataset.accountEdit);if(b?.dataset.accountToggle)toggleAccount(b.dataset.accountToggle);if(b?.dataset.accountDelete)openAccountDelete(b.dataset.accountDelete)});
$('#importLegacy').addEventListener('click',()=>{const legacy=readLegacy();if(!legacy.items.length)return;if(!confirm('このブラウザにログイン機能の追加前から保存されている学びを、'+currentUser.email+' に取り込みますか？'))return;const ids=new Set(state.items.map(x=>x.id));state.items.push(...legacy.items.filter(x=>!ids.has(x.id)));state.categories=[...new Set([...state.categories,...legacy.categories])];const logs=new Set(state.logs.map(x=>JSON.stringify(x)));state.logs.push(...legacy.logs.filter(x=>!logs.has(JSON.stringify(x))));if(save()){render();toast('以前の学びを取り込みました')}});
$('#downloadPending').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='knight-unsynced-learning.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
$('#reloadCloud').addEventListener('click',async()=>{if(!confirm('端末の未保存の変更を破棄し、サーバーのデータを読み込みますか？必要なら先にダウンロードしてください。'))return;try{localStorage.removeItem(cacheKey());dirty=false;await loadLearning()}catch(e){$('#recoveryMessage').textContent=e.message}});

function openAccountDelete(id){if(!currentUser?.isMaster)return;const a=accounts.find(x=>x.user_id===id);if(!a?.managed_by_knight||a.user_id===currentUser.id)return;pendingDeleteId=id;$('#deleteAccountEmail').textContent=a.email;$('#deleteAccountError').hidden=true;$('#confirmAccountDelete').disabled=false;$('#deleteAccountDialog').showModal()}
function cancelAccountDelete(){if($('#confirmAccountDelete').disabled)return;pendingDeleteId=null;$('#deleteAccountDialog').close()}
async function deleteAccount(){if(!currentUser?.isMaster||!pendingDeleteId)return;const id=pendingDeleteId;$('#confirmAccountDelete').disabled=true;$('#deleteAccountError').hidden=true;try{await api('/api/admin',{method:'POST',body:JSON.stringify({action:'delete',userId:id})});try{localStorage.removeItem(KEY+':account:'+id)}catch{}if(adminEditId===id)resetAdminForm(false);pendingDeleteId=null;$('#deleteAccountDialog').close();await loadAccounts();toast('アカウントを削除しました')}catch(e){$('#deleteAccountError').textContent=e.message;$('#deleteAccountError').hidden=false}finally{$('#confirmAccountDelete').disabled=false}}
$('#confirmAccountDelete').addEventListener('click',deleteAccount);$('#cancelAccountDelete').addEventListener('click',cancelAccountDelete);$('#cancelAccountDeleteTop').addEventListener('click',cancelAccountDelete);$('#deleteAccountDialog').addEventListener('cancel',e=>{e.preventDefault();cancelAccountDelete()});

function renderEffort(){
 const e=effortSummary(state.items,state.logs),weekdays=['日','月','火','水','木','金','土'];
 $('#effort').innerHTML=`<div class="effort-heading"><div><span class="eyebrow">YOUR LITTLE WINS</span></div><span class="effort-spark" aria-hidden="true">✧</span></div>
 <div class="effort-metrics"><div><span>連続学習</span><strong>${e.streak}<small>日</small></strong></div><div><span>この7日間の復習</span><strong>${e.weekReviews}<small>回</small></strong></div><div><span>学習した日</span><strong>${e.learningDays}<small>日</small></strong></div></div>
 <div class="effort-bottom"><div class="effort-calendar"><div class="effort-caption"><h3>この28日間の足あと</h3><span>この7日間は ${e.weekDays}日 活動</span></div><div class="effort-weekdays" aria-hidden="true">${e.recent.slice(0,7).map(d=>`<span>${weekdays[d.weekday]}</span>`).join('')}</div><div class="effort-days" role="list" aria-label="最近28日間の学習記録">${e.recent.map(d=>{const count=d.reviews+d.created,level=count===0?0:count<3?1:count<6?2:3,detail=`${new Intl.DateTimeFormat('ja-JP',{month:'long',day:'numeric'}).format(d.date)}：登録${d.created}件、復習${d.reviews}回`;return `<div role="listitem" tabindex="0" class="effort-day level-${level}${d.today?' is-today':''}" title="${detail}" aria-label="${detail}${d.today?'（今日）':''}"><span aria-hidden="true">${d.day}</span></div>`}).join('')}</div><div class="effort-legend"><div aria-hidden="true">少 <i></i><i></i><i></i><i></i> 多</div></div></div>
 <div class="effort-milestone"><span class="effort-badge" aria-hidden="true">♞</span><span class="eyebrow">NEXT LITTLE WIN</span><h3>次は、復習${e.nextMilestone}回。</h3><p>あと <strong>${e.remaining}回</strong> の積み重ねで達成。</p><div class="effort-progress" role="progressbar" aria-label="次の復習目標までの進捗" aria-valuenow="${e.progress}" aria-valuemin="0" aria-valuemax="100"><span style="width:${e.progress}%"></span></div><small>これまでに ${e.totalReviews}回 復習しました</small></div></div>`;
}

function renderProfile(){if(!currentUser)return;$$('[data-current-avatar]').forEach(el=>{el.innerHTML=avatarContents(currentUser.avatarData);el.classList.toggle('has-image',!!currentUser.avatarData)});$('#profileEmail').textContent=currentUser.displayName||currentUser.email;$('#profileEmail').title=currentUser.email;$('#profileRole').textContent=currentUser.isMaster?'マスターユーザー':'あなたの学習スペース'}
async function submitProfile(event){event.preventDefault();if(!currentUser)return;const owner=currentUser.id,input=$('#profileName'),button=$('#profileSave'),error=$('#profileError');button.disabled=true;error.hidden=true;try{const result=await api('/api/profile',{method:'PATCH',body:JSON.stringify({displayName:input.value,...(profileAvatarData!==null?{avatarData:profileAvatarData}:{})})});if(currentUser?.id!==owner)return;currentUser=result.user;input.value=currentUser.displayName;renderProfile();const preview=$('.profile-current-avatar');if(preview)preview.innerHTML=avatarMarkup(currentUser.avatarData,'あなたのアイコン');toast('プロフィールを変更しました')}catch(e){error.textContent=e.message;error.hidden=false}finally{button.disabled=false}}
document.addEventListener('submit',event=>{if(event.target.id==='profileForm')submitProfile(event)});

function avatarContents(data){return data?`<img src="${escapeHTML(data)}" alt="" decoding="async">`:'K'}
function avatarMarkup(data,label){return `<span class="avatar${data?' has-image':''}" role="img" aria-label="${escapeHTML(label)}">${avatarContents(data)}</span>`}
function avatarEditor(prefix,data){return `<div class="avatar-edit-preview" id="${prefix}AvatarPreview">${avatarMarkup(data,'選択中のアイコン')}</div><div class="avatar-edit-controls"><label class="secondary avatar-picker">画像を選ぶ<input id="${prefix}AvatarFile" data-avatar-file="${prefix}" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="text-button" type="button" data-avatar-remove="${prefix}">画像を削除</button><small>PNG・JPEG・WebP / 大きい画像は自動で縮小・圧縮<br>既存アカウントのアイコンは選択後に自動保存されます</small></div><p class="avatar-status" id="${prefix}AvatarStatus" role="status" hidden></p><p class="category-error avatar-error" id="${prefix}AvatarError" role="alert" hidden></p>`}
let avatarReadVersion={admin:0,profile:0};
async function saveSelectedAvatar(prefix,image,target,owner){
 if(prefix==='admin'&&!target){adminAvatarData=image;return false}
 const result=await api(prefix==='admin'?'/api/admin':'/api/profile',{method:prefix==='admin'?'POST':'PATCH',body:JSON.stringify(prefix==='admin'?{action:'update',userId:target,avatarData:image}:{avatarData:image})});
 if(currentUser?.id!==owner)return true;
 if(prefix==='profile'){currentUser={...currentUser,avatarData:result.user.avatarData};profileAvatarData=null;renderProfile()}
 else{const account=accounts.find(a=>a.user_id===target);if(account)account.avatar_data=image;if(adminEditId===target)adminAvatarData=image;if(target===owner){currentUser.avatarData=image;renderProfile()}renderAccounts()}
 return true;
}
async function updateSelectedAvatar(prefix,file){
 const version=++avatarReadVersion[prefix],owner=currentUser?.id,target=adminEditId;
 const error=$('#'+prefix+'AvatarError'),status=$('#'+prefix+'AvatarStatus'),save=$('#'+(prefix==='admin'?'adminSubmit':'profileSave')),input=$('#'+prefix+'AvatarFile'),remove=$('[data-avatar-remove="'+prefix+'"]');
 error.hidden=true;status.textContent=file?'画像を縮小・保存しています…':'画像を削除しています…';status.hidden=false;save.disabled=true;input.disabled=true;remove.disabled=true;
 try{
  const image=file?await prepareAvatar(file):'';
  if(version!==avatarReadVersion[prefix]||currentUser?.id!==owner||(prefix==='admin'&&adminEditId!==target))return;
  const saved=await saveSelectedAvatar(prefix,image,target,owner);
  if(version!==avatarReadVersion[prefix]||currentUser?.id!==owner||(prefix==='admin'&&adminEditId!==target))return;
  $('#'+prefix+'AvatarPreview').innerHTML=avatarMarkup(image,'選択中のアイコン');
  const currentPreview=$('.profile-current-avatar');if(currentPreview&&(prefix==='profile'||target===owner))currentPreview.innerHTML=avatarMarkup(image,'あなたのアイコン');
  status.textContent=saved?(image?'アイコンを保存しました':'アイコンを削除しました'):'アカウントの追加時にアイコンも保存されます';
 }catch(e){error.textContent=e.message;error.hidden=false;status.hidden=true}
 finally{if(version===avatarReadVersion[prefix]){save.disabled=false;input.disabled=false;remove.disabled=false}input.value=''}
}
document.addEventListener('change',event=>{const prefix=event.target.dataset.avatarFile;if(prefix&&event.target.files?.[0])updateSelectedAvatar(prefix,event.target.files[0])});
document.addEventListener('click',event=>{const button=event.target.closest('[data-avatar-remove]');if(button)updateSelectedAvatar(button.dataset.avatarRemove,null)});
document.addEventListener('error',event=>{if(event.target.matches?.('.avatar img')){const parent=event.target.parentElement;parent.textContent='K';parent.classList.remove('has-image')}},true);
// Keep the management upload control ready before the first visit.
$('#adminAvatarEditor').innerHTML=avatarEditor('admin','');

function renderAdminTarget(){
 const selected=adminCreateMode?'__new__':adminEditId||currentUser.id;
 $('#adminTarget').innerHTML=accounts.map(a=>`<option value="${a.user_id}">${escapeHTML(a.display_name||'名前未設定')}（${escapeHTML(a.email)}）${a.user_id===currentUser.id?' · 自分':''}</option>`).join('')+'<option value="__new__">＋ 新しい利用者を追加</option>';
 $('#adminTarget').value=selected;
}
$('#adminTarget').addEventListener('change',event=>{if(event.target.value==='__new__')resetAdminForm(true);else editAccount(event.target.value)});
